def _b64_to_image_reader(b64_str: str):
    """Return a ReportLab ImageReader from a base64-encoded PNG string.
    ReportLab's canvas.drawImage() requires an ImageReader (or file path),
    NOT a raw BytesIO — this wrapper provides the correct object."""
    try:
        from reportlab.lib.utils import ImageReader  # pyrefly: ignore [missing-import]
        return ImageReader(_io.BytesIO(base64.b64decode(b64_str)))
    except Exception:
        # Fallback: write to a temp file and return the path.
        # Register for deletion at interpreter exit to avoid temp file leaks.
        import tempfile, atexit
        with tempfile.NamedTemporaryFile(suffix=".png", delete=False) as _tmp_img:
            _tmp_img.write(base64.b64decode(b64_str))
            tmp = _tmp_img.name
        atexit.register(lambda p=tmp: os.path.exists(p) and os.remove(p))
        return tmp


