def _render_fixed_front_pages(
    canvas_obj,
    page_width_pt: float,
    page_height_pt: float,
    book_title: str,
    author_name: str,
    devanagari_font: str,
    latin_font: str,
    body_font_size: float,
) -> None:
    """
    Render the two fixed publisher front pages directly onto the ReportLab canvas.

    Page 1 — Title page (matches the reference PDF exactly):
      - Large bold Devanagari title, upper-centre
      - Author name in smaller text, mid-page
      - Kavya Publications logo (monochrome), bottom-centre

    Page 2 — Copyright / imprint page:
      - SDR Innoways logo (top-left)
      - Kavya Publications logo (colour, top-left beside SDR)
      - Publisher contact details (Times-Roman)
      - ISBN, Price, Year block
      - Copyright paragraph
      - All Rights Reserved paragraph

    Only book_title and author_name change between books.
    Everything else is fixed publisher boilerplate.
    """
    from reportlab.lib.units import mm
    from reportlab.lib.colors import black, Color
    try:
        from PIL import Image as _PilImage  # pyrefly: ignore [missing-import]
    except ImportError:
        _PilImage = None  # type: ignore[assignment]
        logger.warning("⚠️  Pillow (PIL) not installed — logo/image dimensions on front pages will use fallback sizing. Add 'Pillow' to requirements.txt")

    c = canvas_obj
    W = page_width_pt
    H = page_height_pt

    # ── Margin constants (mirroring the reference layout) ──────────────────────
    LEFT_M  = 20 * mm
    RIGHT_M = 20 * mm
    TEXT_W  = W - LEFT_M - RIGHT_M

    # ════════════════════════════════════════════════════════════════════════
    # PAGE 1 — Title page
    # ════════════════════════════════════════════════════════════════════════
    c.setFillColor(black)

    # ── Title block ─────────────────────────────────────────────────────────
    # Two lines of title text, very large, bold, centred
    # For Devanagari: use the registered NotoSerifDevanagari or NotoSansDevanagari
    TITLE_FONT_SIZE = 64   # large display size — matches the reference
    TITLE_FONT_BOLD = devanagari_font  # Noto fonts don't have a separate bold TTF
                                        # registered; use the regular and scale up

    title_lines = book_title.split("\n") if "\n" in book_title else [book_title]
    # If title has a "/" or common Hindi separators, split there too
    if len(title_lines) == 1 and len(book_title) > 10:
        # Try to split intelligently at a space near midpoint
        words = book_title.split()
        if len(words) >= 2:
            mid = len(words) // 2
            title_lines = [" ".join(words[:mid]), " ".join(words[mid:])]

    # Draw title starting from ~top 25% of page
    title_y = H - (H * 0.18) - TITLE_FONT_SIZE
    c.setFont(devanagari_font, TITLE_FONT_SIZE)
    for i, line in enumerate(title_lines[:3]):  # max 3 lines
        c.drawCentredString(W / 2, title_y - i * (TITLE_FONT_SIZE * 1.25), line)

    # ── Author name ─────────────────────────────────────────────────────────
    AUTHOR_FONT_SIZE = 20
    author_y = H * 0.42  # roughly 42% from bottom = mid-lower area
    c.setFont(devanagari_font, AUTHOR_FONT_SIZE)
    c.drawString(LEFT_M, author_y, author_name)

    # ── Kavya logo (monochrome) at bottom centre ─────────────────────────────
    try:
        _kbw_bytes = base64.b64decode(_KAVYA_BW_PNG_B64)
        if _PilImage is not None:
            pil_img = _PilImage.open(_io.BytesIO(_kbw_bytes))
            orig_w, orig_h = pil_img.size
        else:
            orig_w, orig_h = 1, 1  # fallback 1:1 aspect ratio
        logo_w  = 48 * mm
        logo_h  = logo_w * orig_h / orig_w
        logo_x  = (W - logo_w) / 2
        logo_y  = 18 * mm
        logo_img = _b64_to_image_reader(_KAVYA_BW_PNG_B64)
        c.drawImage(logo_img, logo_x, logo_y, width=logo_w, height=logo_h,
                    mask="auto")
    except Exception as e:
        print(f"  ⚠️  Page-1 logo draw failed: {e}")

    c.showPage()  # end of page 1

    # ════════════════════════════════════════════════════════════════════════
    # PAGE 2 — Publisher / Copyright page
    # ════════════════════════════════════════════════════════════════════════
    import datetime as _dt

    c.setFillColor(black)
    BODY_SIZE   = 10.5
    SMALL_SIZE  = 9.5
    BOLD_FONT   = "Times-Roman"  # ReportLab has no built-in bold; we use drawString
                                  # with a slightly larger size for emphasis labels
    LINE_H      = BODY_SIZE * 1.55

    y = H - 18 * mm  # start near top

    # ── "Publisher:" bold label ──────────────────────────────────────────────
    c.setFont("Times-Roman", 13)
    c.drawString(LEFT_M, y, "Publisher:")
    y -= 6 * mm

